'use strict';

/**
 * Generate harness-specific files from the single source of truth
 * (agents/, commands/, rules/trading/, skills/): one canonical tree, with
 * per-harness adapters derived from it. Generated files are committed and a
 * test fails when they drift (`node scripts/sync-harness.js --check`).
 *
 *   workspace/AGENTS.md, CLAUDE.md, QWEN.md   operator instructions for any harness (AGENTS.md with the skill
 *                                             catalog; QWEN.md, which CLAUDE.md imports, without it)
 *   .codex/agents/<role>.toml                 Codex agent roles
 *   workspace/opencode.json                   opencode project config: MCP servers, roles as
 *                                             subagents, permissions (scripts/lib/opencode.js); its role
 *                                             prompts in the FTH_ROLE_SKILLS mode (role-skills.js; the
 *                                             committed file is the default, index)
 *   qwen-extension/                           Qwen Code extension (install with
 *     qwen-extension.json, QWEN.md            `qwen extensions link`): generated
 *     agents/<role>.md, commands/<name>.md    Qwen-format agents and commands, plus
 *     skills, scripts, strategies, hooks,     symlinks to the shared sources so
 *     accounts -> ../<dir>                    there is a single harness root (the
 *                                             rules are embedded in QWEN.md, not linked)
 */

const fs = require('fs');
const path = require('path');
const { parseFrontmatter } = require('./frontmatter');
const { SERVER_NAME: HARNESS_SERVER } = require('./harness-tools/registry');
const opencode = require('./opencode');
const roleSkills = require('./role-skills');
const { headPlan } = require('./head-prompt');

const GENERATED = '<!-- Generated by scripts/sync-harness.js. Edit the sources, not this file. -->';
const TOML_GENERATED = '# Generated by scripts/sync-harness.js from agents/<role>.md. Edit the source, not this file.';

const QWEN_TOOLS = {
  Read: 'read_file', Write: 'write_file', Edit: 'edit', Bash: 'run_shell_command', Grep: 'grep_search',
  Glob: 'glob', WebSearch: 'web_search', WebFetch: 'web_fetch', Skill: 'skill', Agent: 'task',
};
// Agents that only analyse may write scratch files; nobody needs network sandbox access.
const CODEX_SANDBOX = { default: 'read-only', writes: 'workspace-write' };

function readSorted(dir, suffix) {
  return fs.readdirSync(dir).filter(f => f.endsWith(suffix)).sort();
}

function loadAgents(root) {
  return readSorted(path.join(root, 'agents'), '.md').map(f => {
    const { data, body } = parseFrontmatter(fs.readFileSync(path.join(root, 'agents', f), 'utf8'));
    // `role-skills`: the skills the role's body says to load (a key no harness interprets; opencode's roles embed them).
    const skills = Array.isArray(data['role-skills']) ? data['role-skills'].map(String) : [];
    // `role-index`: the skills its body says to look up as needed (role-skills.js: indexed in opencode's index mode).
    const index = Array.isArray(data['role-index']) ? data['role-index'].map(String) : [];
    return { file: f, ...data, tools: String(data.tools || '').split(',').map(t => t.trim()).filter(Boolean), skills, index, body: body.trim() };
  });
}

/**
 * An agent's declared skills (frontmatter `role-skills`, then `role-index`) as { name, body, description }, from
 * skills/<name>/SKILL.md; a missing one throws.
 */
function agentSkills(root, agent) {
  return [...agent.skills, ...(agent.index || [])].map(name => {
    const file = path.join(root, 'skills', name, 'SKILL.md');
    if (!fs.existsSync(file)) throw new Error(`agents/${agent.file}: skill "${name}" has no skills/${name}/SKILL.md`);
    const { data, body } = parseFrontmatter(fs.readFileSync(file, 'utf8'));
    return { name, body: body.trim(), description: String(data.description || '') };
  });
}

function tomlString(text) {
  // Multi-line literal strings can't contain ''' ; fall back to an escaped basic string.
  if (!text.includes("'''")) return `'''\n${text}\n'''`;
  return JSON.stringify(text);
}

function codexAgentToml(agent) {
  const writes = agent.tools.some(t => ['Write', 'Edit', 'Bash'].includes(t));
  const mcp = agent.tools.filter(t => t.startsWith('mcp__broker__')).map(t => t.replace('mcp__broker__', ''));
  const tools = agent.tools.filter(t => t.startsWith(`mcp__${HARNESS_SERVER}__`)).map(t => t.replace(`mcp__${HARNESS_SERVER}__`, ''));
  const instructions = [
    `You are the ${agent.name} role of the futures trading harness. ${agent.description}`,
    mcp.length ? `broker MCP tools you may use: ${mcp.join(', ')}. Do not call any other broker tool.` : 'Do not call any broker MCP tool.',
    tools.length ? `${HARNESS_SERVER} MCP tools you may use: ${tools.join(', ')}. Do not call any other ${HARNESS_SERVER} tool.` : `Do not call any ${HARNESS_SERVER} MCP tool.`,
    // A role without Read: Codex's read-only sandbox still lets a shell read files, so say it.
    ...(agent.tools.includes('Read') ? [] : [`Do not read files (no shell reads either), except your skills (${[...(agent.skills || []), ...(agent.index || [])].map(s => `skills/${s}/SKILL.md`).join(', ') || 'none'} under the harness root): take bars and market data only through the tools above.`]),
    '',
    agent.body,
  ].join('\n');
  return [
    TOML_GENERATED,
    `sandbox_mode = "${writes ? CODEX_SANDBOX.writes : CODEX_SANDBOX.default}"`,
    '',
    `developer_instructions = ${tomlString(instructions)}`,
    '',
  ].join('\n');
}

function codexRoleName(name) {
  return name.replace(/-/g, '_');
}

function codexAgentsTable(agents, configDir) {
  return agents.flatMap(a => [
    `[agents.${codexRoleName(a.name)}]`,
    `description = ${JSON.stringify(a.description)}`,
    `config_file = ${JSON.stringify(path.posix.join(configDir, `${a.name}.toml`))}`,
    '',
  ]).join('\n');
}

function qwenAgentMd(agent) {
  const tools = agent.tools.map(t => QWEN_TOOLS[t] || t);
  return [
    '---',
    `name: ${agent.name}`,
    `description: ${JSON.stringify(agent.description)}`,
    'tools:',
    ...tools.map(t => `  - ${t}`),
    // Headless runs: the role asks (and so is refused) for anything the workspace allowlist doesn't allow.
    'approvalMode: default',
    // Qwen runs a named subagent in the background unless told otherwise; the head trader waits for each role.
    'background: false',
    '---',
    '',
    GENERATED,
    '',
    agent.body,
    '',
  ].join('\n');
}

function qwenCommandMd(text) {
  const { data, body } = parseFrontmatter(text);
  return [
    '---',
    `description: ${JSON.stringify(data.description)}`,
    '---',
    '',
    body.trim().replace(/\$ARGUMENTS/g, '{{args}}'),
    '',
  ].join('\n');
}

/**
 * The operator instructions. `catalog`: the Skills section lists every skill (name, path, description), for a harness
 * with no skill listing of its own (Codex reads AGENTS.md as its only list; opencode's head trader in index mode, which
 * has no skill tool, reads it as its index). Without it (QWEN.md, which Claude Code's CLAUDE.md imports too) the
 * section is one line: Qwen Code and Claude Code list every skill themselves, so the catalog would be the same text twice.
 */
function workspaceAgentsMd(root, { catalog = true } = {}) {
  const rules = readSorted(path.join(root, 'rules', 'trading'), '.md')
    .map(f => fs.readFileSync(path.join(root, 'rules', 'trading', f), 'utf8').trim().replace(/^# /m, '## '));
  const skills = fs.readdirSync(path.join(root, 'skills'))
    .filter(d => fs.existsSync(path.join(root, 'skills', d, 'SKILL.md')))
    .sort()
    .map(d => {
      const { data } = parseFrontmatter(fs.readFileSync(path.join(root, 'skills', d, 'SKILL.md'), 'utf8'));
      return `- \`${d}\` (skills/${d}/SKILL.md): ${data.description}`;
    });
  const agents = loadAgents(root).map(a => `- \`${a.name}\` (agents/${a.name}.md): ${a.description}`);
  return [
    GENERATED,
    '',
    '# Futures Trading Harness: Operator Instructions',
    '',
    'You are the head trader of an automated futures desk trading a prop firm or',
    'broker account through the `broker` MCP server. These instructions apply to every',
    'harness (Claude Code, Codex, Qwen Code, opencode, or any agent that reads AGENTS.md).',
    '',
    '## Start here',
    '',
    '- The harness root (`<root>`, also in `FTH_ROOT` and the session briefing) is the',
    '  absolute path of the parent of this `workspace/` folder. Strategies are in',
    '  `<root>/strategies/`. Always write absolute paths.',
    '- The harness\'s operations (bars, strategy scans, the market snapshot, the',
    '  multi-timeframe read, blackouts, the prop status, lessons, reconcile) are',
    '  tools on the `harness` MCP server (the `tool-arguments` skill). Use the tools;',
    '  the scripts in `<root>/scripts/` are for people (`user-commands`).',
    '- Before trading, load the skill you need yourself (your skill tool; without one,',
    '  the `skill_lookup` tool or `<root>/skills/<name>/SKILL.md`), never through a',
    '  role: a role\'s call is its own analysis. Start with `trade-session`,',
    '  `premarket`, `end-of-day`, or `autonomous-trading`.',
    '- Strategies are Markdown files: the `strategies_list` tool lists them.',
    '- Delegate to the agent roles below with your harness\'s subagents; without',
    '  subagents, read the role file and play the role yourself.',
    '',
    '## Rules (always apply)',
    '',
    ...rules.flatMap(r => [r, '']),
    '## Skills',
    '',
    ...(catalog ? skills : ['Your harness lists every skill (its skill tool); each is `<root>/skills/<name>/SKILL.md`.']),
    '',
    '## Agent roles',
    '',
    ...agents,
    '',
  ].join('\n');
}

function qwenExtensionJson(root) {
  const { version } = JSON.parse(fs.readFileSync(path.join(root, 'package.json'), 'utf8'));
  return `${JSON.stringify({
    name: 'futures-trading-harness',
    version,
    contextFileName: 'QWEN.md',
    mcpServers: {
      // The gateway starts the broker MCP server named in the broker config
      // (mcp-configs/brokers.json, ~/.futures-trading-harness/brokers.json). A settings.json
      // entry named "broker" (written by scripts/install.js) takes precedence.
      broker: { command: 'node', args: ['${extensionPath}${/}scripts${/}mcp-gateway.js'], cwd: '${extensionPath}', timeout: 60000 },
      // The harness's own operations as tools (scripts/harness-tools-mcp.js; no order tools).
      [HARNESS_SERVER]: { command: 'node', args: ['${extensionPath}${/}scripts${/}harness-tools-mcp.js'], cwd: '${extensionPath}', timeout: 60000 },
    },
  }, null, 2)}\n`;
}

/** The agents' role-index problems (role-skills.js planErrors); throws on any. */
function checkRoleSkills(root) {
  const skills = fs.readdirSync(path.join(root, 'skills')).filter(d => fs.existsSync(path.join(root, 'skills', d, 'SKILL.md')));
  const dir = path.join(root, 'strategies');
  const strategies = fs.existsSync(dir) ? fs.readdirSync(dir).filter(d => fs.existsSync(path.join(dir, d, 'STRATEGY.md'))) : null;
  const errors = roleSkills.planErrors(loadAgents(root), skills, strategies);
  if (errors.length) throw new Error(`role skills:\n  ${errors.join('\n  ')}`);
}

/**
 * workspace/opencode.json: the opencode adapter (scripts/lib/opencode.js), its role prompts in `mode`
 * (role-skills.js: index, the default, or full).
 */
function opencodeJson(root, { mode = roleSkills.DEFAULT_MODE } = {}) {
  const agents = loadAgents(root).map(a => {
    const skillDocs = agentSkills(root, a);
    return { ...a, skillDocs, skillPlan: roleSkills.skillPlan(a, skillDocs, mode) };
  });
  // The head trader's own prompt: its per-cycle skills embedded in index mode, none in full mode (head-prompt.js).
  return `${JSON.stringify(opencode.workspaceConfig(agents, headPlan(root, mode)), null, 2)}\n`;
}

/** Shared directories the Qwen extension links to instead of copying. */
const QWEN_LINKS = ['skills', 'scripts', 'strategies', 'hooks', 'accounts'];
/** Links an older sync made that are no longer wanted: rules are embedded in QWEN.md (contextFileName); models went with the trained policy. */
const QWEN_STALE_LINKS = ['rules', 'models'];

/** Map of relative path -> expected file content. */
function expectedFiles(root, { mode = roleSkills.DEFAULT_MODE } = {}) {
  checkRoleSkills(root);
  const files = {};
  const agentsMd = workspaceAgentsMd(root);
  files['workspace/AGENTS.md'] = agentsMd;
  // Claude Code and Qwen Code list every skill themselves: their instructions leave the catalog out (workspaceAgentsMd).
  const listed = workspaceAgentsMd(root, { catalog: false });
  files['workspace/CLAUDE.md'] = `${GENERATED}\n\n@QWEN.md\n`;
  files['workspace/QWEN.md'] = listed;
  files['qwen-extension/QWEN.md'] = listed;
  files['workspace/opencode.json'] = opencodeJson(root, { mode });
  files['qwen-extension/qwen-extension.json'] = qwenExtensionJson(root);
  for (const a of loadAgents(root)) {
    files[`.codex/agents/${a.name}.toml`] = codexAgentToml(a);
    files[`qwen-extension/agents/${a.name}.md`] = qwenAgentMd(a);
  }
  for (const f of readSorted(path.join(root, 'commands'), '.md')) {
    files[`qwen-extension/commands/${f}`] = qwenCommandMd(fs.readFileSync(path.join(root, 'commands', f), 'utf8'));
  }
  return files;
}

/** Generated directories whose stale files should be removed. */
const OWNED_DIRS = ['.codex/agents', 'qwen-extension/agents', 'qwen-extension/commands'];

function syncLinks(root, check, stale) {
  for (const name of QWEN_LINKS) {
    const link = path.join(root, 'qwen-extension', name);
    const target = `../${name}`;
    let current;
    try {
      current = fs.lstatSync(link).isSymbolicLink() ? fs.readlinkSync(link) : 'not-a-link';
    } catch (_err) {
      current = null;
    }
    if (current === target) continue;
    stale.push(`qwen-extension/${name} -> ${target}`);
    if (check) continue;
    if (current !== null) fs.rmSync(link, { recursive: true, force: true });
    fs.mkdirSync(path.dirname(link), { recursive: true });
    fs.symlinkSync(target, link, 'dir');
  }
}

function removeStaleLinks(root, check, stale) {
  for (const name of QWEN_STALE_LINKS) {
    const link = path.join(root, 'qwen-extension', name);
    let isLink;
    try {
      isLink = fs.lstatSync(link).isSymbolicLink();
    } catch (_err) {
      continue;
    }
    if (!isLink) continue; // never remove a real directory someone put there
    stale.push(`qwen-extension/${name} (stale link)`);
    if (!check) fs.unlinkSync(link);
  }
}

function syncHarness(root, { check = false, mode = roleSkills.DEFAULT_MODE } = {}) {
  const expected = expectedFiles(root, { mode });
  const stale = [];
  for (const [rel, content] of Object.entries(expected)) {
    const file = path.join(root, rel);
    const current = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : null;
    if (current === content) continue;
    stale.push(rel);
    if (!check) {
      fs.mkdirSync(path.dirname(file), { recursive: true });
      fs.writeFileSync(file, content);
    }
  }
  syncLinks(root, check, stale);
  removeStaleLinks(root, check, stale);
  for (const dir of OWNED_DIRS) {
    const abs = path.join(root, dir);
    if (!fs.existsSync(abs)) continue;
    for (const f of fs.readdirSync(abs)) {
      const rel = `${dir}/${f}`;
      if (expected[rel] !== undefined) continue;
      stale.push(`${rel} (orphan)`);
      if (!check) fs.unlinkSync(path.join(abs, f));
    }
  }
  return stale;
}

module.exports = {
  QWEN_TOOLS,
  loadAgents,
  agentSkills,
  codexAgentToml,
  codexRoleName,
  codexAgentsTable,
  qwenAgentMd,
  qwenCommandMd,
  workspaceAgentsMd,
  expectedFiles,
  QWEN_LINKS,
  QWEN_STALE_LINKS,
  qwenExtensionJson,
  opencodeJson,
  checkRoleSkills,
  syncHarness,
};
